#!/usr/bin/env nix-shell
#!nix-shell -i bash -p jq

set -euo pipefail

commit=$(git ls-remote https://github.com/NixOS/nixpkgs nixpkgs-unstable | cut -f1)
url="https://github.com/NixOS/nixpkgs/archive/$commit.tar.gz"
hash=$(nix store prefetch-file --json --unpack "$url" | jq -r .hash)

cat > nixpkgs.nix <<EOF
# DO NOT EDIT MANUALLY
# This file is auto-generated by update-nixpkgs.sh
fetchTarball {
  url = "$url";
  sha256 = "$hash";
}
EOF
